def transform(g):
    g=[row[:] for row in g]
    H,W=len(g),len(g[0])
    # find pattern: contiguous line of non-background, non-marker colors
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    # pattern = maximal run of a color != bg (length>=2) horizontal or vertical
    def runs():
        out=[]
        for i in range(H):
            j=0
            while j<W:
                if g[i][j]!=bg:
                    k=j
                    while k<W and g[i][k]==g[i][j]: k+=1
                    if k-j>=2: out.append(('h',i,j,g[i][j],k-j))
                    j=k
                else: j+=1
        for j in range(W):
            i=0
            while i<H:
                if g[i][j]!=bg:
                    k=i
                    while k<H and g[k][j]==g[k][i]: k+=1
                    if k-i>=2: out.append(('v',i,j,g[i][j],k-i))
                    i=k
                else: i+=1
        return out
    # find the multicolor contiguous line (pattern has distinct colors)
    best=None
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg:
                if j+2<W and g[i][j+1]!=bg and g[i][j+2]!=bg:
                    best=('h',i,j,[g[i][j],g[i][j+1],g[i][j+2]])
                if i+2<H and g[i+1][j]!=bg and g[i+2][j]!=bg:
                    best=('v',i,j,[g[i][j],g[i+1][j],g[i+2][j]])
    ori,pr,pc,pcol=best
    colors=set(pcol)
    markers=[(i,j) for i in range(H) for j in range(W) if g[i][j] not in colors and (i,j)!=(pr,pc)]
    # exclude cells that are part of other pattern? demo: markers=1 only; marker color = most common non-bg
    mc=Counter(g[i][j] for i,j in markers).most_common(1)[0][0]
    markers=[(i,j) for i,j in markers if g[i][j]==mc]
    out=[row[:] for row in g]
    for i,j in markers:
        if ori=='h':
            if j-1>=0 and j+1<W:
                out[i][j-1],out[i][j],out[i][j+1]=pcol
        else:
            if i-1>=0 and i+1<H:
                out[i-1][j],out[i][j],out[i+1][j]=pcol
    return out

